create table public.learning_path_versions(id uuid primary key default gen_random_uuid(),path_key text not null,version integer not null,title_en text not null,title_hi text,role_slug text not null,skill_sequence jsonb not null,status text not null default 'draft' check(status in ('draft','review','approved','published','retired')),created_by uuid not null references auth.users(id),published_at timestamptz,unique(path_key,version));
create table public.content_approvals(id uuid primary key default gen_random_uuid(),resource_id uuid references public.external_resources(id),path_version_id uuid references public.learning_path_versions(id),gate text not null check(gate in ('technical','translation','accessibility','assessment','legal')),reviewer_id uuid not null references auth.users(id),decision text not null check(decision in ('approved','changes_requested','rejected')),note text,created_at timestamptz not null default now(),check(resource_id is not null or path_version_id is not null));
create table public.question_blueprints(id uuid primary key default gen_random_uuid(),organization_id uuid references public.organizations(id),title text not null,role_slug text not null,version integer not null,skill_distribution jsonb not null,difficulty_distribution jsonb not null,status text not null default 'draft' check(status in ('draft','review','approved','retired')),created_by uuid not null references auth.users(id),unique(organization_id,title,version));
create table public.cohort_assignments(id uuid primary key default gen_random_uuid(),cohort_id uuid not null references public.cohorts(id) on delete cascade,path_version_id uuid not null references public.learning_path_versions(id),assigned_by uuid not null references auth.users(id),due_at timestamptz,status text not null default 'active' check(status in ('draft','active','closed','cancelled')),created_at timestamptz not null default now());
alter table public.learning_path_versions enable row level security;alter table public.content_approvals enable row level security;alter table public.question_blueprints enable row level security;alter table public.cohort_assignments enable row level security;create policy "published paths readable" on public.learning_path_versions for select using(status='published' or public.is_platform_staff());create policy "staff manage path versions" on public.learning_path_versions for all using(public.is_platform_staff()) with check(public.is_platform_staff());create policy "reviewers manage approvals" on public.content_approvals for all using(public.is_platform_staff()) with check(public.is_platform_staff());create policy "institute members manage blueprints" on public.question_blueprints for all using(organization_id is null and public.is_platform_staff() or organization_id is not null and public.is_active_org_member(organization_id)) with check(organization_id is null and public.is_platform_staff() or organization_id is not null and public.is_active_org_member(organization_id));
